CREATE OR REPLACE FUNCTION public.batal_draft(p_id uuid, p_alasan text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare d pesanan_draft;
begin
  select * into d from pesanan_draft where id = p_id for update;
  if d.id is null or d.status <> 'draft' then raise exception 'Draft tidak ditemukan atau sudah selesai'; end if;
  if not peran_di_outlet(d.outlet_id, '{kasir,spv}') then raise exception 'Tidak diizinkan'; end if;
  if coalesce(trim(p_alasan), '') = '' then raise exception 'Alasan pembatalan wajib diisi'; end if;
  update pesanan_draft set status = 'dibatalkan', alasan_batal = trim(p_alasan), dibatalkan_oleh = auth.uid(), selesai_at = now(), updated_at = now() where id = p_id;
end $function$
;
CREATE OR REPLACE FUNCTION public.boleh_outlet(o uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select exists (
    select 1 from penugasan t
    join pengguna u on u.id = t.pengguna_id and u.status = 'aktif'
    left join outlet x on x.id = o
    where t.pengguna_id = auth.uid()
      and (t.outlet_id = o
           or (t.outlet_id is null and t.peran in ('owner','finance','hrd','admin_pusat','admin_gudang'))
           or (t.peran = 'manajer_area' and t.area_id = x.area_id))
  );
$function$
;
CREATE OR REPLACE FUNCTION public.buat_setoran(p jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare o uuid:=(p->>'outlet_id')::uuid; cid uuid:=(p->>'client_id')::uuid; sid uuid; x jsonb; d date; nominal bigint; rekap jsonb; sisa bigint; nm text;
begin
 if not operasional_boleh(o,'setoran') then raise exception 'Tidak diizinkan'; end if;
 if cid is null then raise exception 'ID pengajuan wajib'; end if;
 perform pg_advisory_xact_lock(hashtext('setoran:'||o));
 select id into sid from setoran_omzet where client_id=cid and outlet_id=o and penyetor_id=auth.uid();
 if sid is not null then return sid; end if;
 if p->>'cara' not in ('tunai','transfer') or length(trim(coalesce(p->>'tujuan','')))<3 or length(trim(coalesce(p->>'penanggung_jawab','')))<3 then raise exception 'Isi cara, tujuan, dan penanggung jawab'; end if;
 if p->>'cara'='tunai' and length(trim(coalesce(p->>'pengambil','')))<3 then raise exception 'Nama pengambil wajib'; end if;
 if (p->>'waktu')::timestamptz is null or (p->>'waktu')::timestamptz>now()+interval '5 minutes' then raise exception 'Waktu penyerahan/transfer tidak valid'; end if;
 if not exists(select 1 from storage.objects where bucket_id='operasional-bukti' and name=p->>'bukti_path' and name like 'setoran/'||o||'/'||auth.uid()||'/%') then raise exception 'Unggah foto pengambil atau bukti transfer'; end if;
 if jsonb_typeof(p->'rincian') is distinct from 'array' or jsonb_array_length(p->'rincian') not between 1 and 93 then raise exception 'Isi rincian tanggal omzet'; end if;
 if exists(select 1 from jsonb_array_elements(p->'rincian') z group by z->>'tanggal' having count(*)>1) then raise exception 'Tanggal omzet berulang'; end if;
 select nama into nm from pengguna where id=auth.uid() and status='aktif';
 if nm is null then raise exception 'Akun tidak aktif'; end if;
 insert into setoran_omzet(client_id,outlet_id,cara,waktu,penyetor_id,penyetor_nama,pengambil,penanggung_jawab,tujuan,bukti_path,catatan)
 values(cid,o,p->>'cara',(p->>'waktu')::timestamptz,auth.uid(),nm,nullif(trim(p->>'pengambil'),''),left(trim(p->>'penanggung_jawab'),150),left(trim(p->>'tujuan'),200),p->>'bukti_path',left(p->>'catatan',1000)) returning id into sid;
 for x in select * from jsonb_array_elements(p->'rincian') loop
   d:=(x->>'tanggal')::date; nominal:=(x->>'jumlah')::bigint;
   if d is null or d>(now() at time zone 'Asia/Jakarta')::date or nominal is null or nominal<=0 then raise exception 'Tanggal/nominal rincian tidak valid'; end if;
   select z into rekap from jsonb_array_elements(rekap_setoran(o,d,d)) z;
   sisa:=(rekap->>'sisa')::bigint;
   if nominal>greatest(sisa,0) then raise exception 'Nominal tanggal % melebihi sisa %; minta Akunting memeriksa POS/catatan harian',d,sisa; end if;
   insert into alokasi_setoran(setoran_id,tanggal,jumlah) values(sid,d,nominal);
 end loop;
 insert into log_aktivitas(pengguna_id,aksi,entitas,entitas_id,nilai_baru) values(auth.uid(),'buat','setoran_omzet',sid::text,p-'bukti_path');
 return sid;
end $function$
;
CREATE OR REPLACE FUNCTION public.buat_transaksi(p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_outlet uuid := (p->>'outlet_id')::uuid;
  v_kanal kanal_jual := (p->>'kanal')::kanal_jual;
  v_sesi uuid; v_id uuid; v_nomor int;
  v_sub bigint := 0; v_hpp bigint := 0; v_diskon bigint := greatest(coalesce((p->>'diskon')::bigint, 0), 0);
  v_total bigint; v_batas int; v_diterima bigint; v_kembali bigint := 0; v_bayar jsonb; v_sum bigint := 0; v_oto otorisasi;
  it jsonb; m menu; v_harga bigint; v_nama text; v_vids uuid[]; v_item_hpp bigint; v_qty int; r record; b jsonb;
begin
  select id into v_id from transaksi where client_id = (p->>'client_id')::uuid;
  if v_id is not null then
    return (select jsonb_build_object('id', id, 'nomor', nomor, 'subtotal', subtotal, 'diskon', diskon, 'total', total, 'kembalian', 0, 'ulang', true) from transaksi where id = v_id);
  end if;
  if not peran_di_outlet(v_outlet, '{kasir,spv}') then raise exception 'Tidak diizinkan bertransaksi di outlet ini'; end if;
  -- sesi aktif perangkat (shift dimulai staf dengan PIN), selain itu shift milik akun yang login
  if nullif(p->>'sesi_id', '') is not null then
    select id into v_sesi from sesi_kas where id = (p->>'sesi_id')::uuid and outlet_id = v_outlet and ditutup_at is null;
  end if;
  if v_sesi is null then
    select id into v_sesi from sesi_kas where outlet_id = v_outlet and kasir_id = auth.uid() and ditutup_at is null;
  end if;
  if v_sesi is null then raise exception 'Buka shift terlebih dahulu'; end if;
  if jsonb_array_length(coalesce(p->'items', '[]')) = 0 then raise exception 'Keranjang kosong'; end if;

  v_id := gen_random_uuid();
  select coalesce(max(nomor), 0) + 1 into v_nomor from transaksi
    where outlet_id = v_outlet and created_at >= date_trunc('day', now() at time zone 'Asia/Jakarta') at time zone 'Asia/Jakarta';

  insert into transaksi (draft_id, id, client_id, outlet_id, sesi_kas_id, nomor, kanal, tipe, pelanggan, meja, catatan, subtotal, total)
    values (nullif(p->>'draft_id', '')::uuid, v_id, (p->>'client_id')::uuid, v_outlet, v_sesi, v_nomor, v_kanal, coalesce(p->>'tipe', 'dine_in'),
            nullif(p->>'pelanggan', ''), nullif(p->>'meja', ''), nullif(p->>'catatan', ''), 0, 0);

  for it in select * from jsonb_array_elements(p->'items') loop
    select * into m from menu where id = (it->>'menu_id')::uuid and deleted_at is null and aktif;
    if m.id is null then raise exception 'Menu tidak tersedia'; end if;
    v_qty := greatest((it->>'qty')::int, 1);
    v_vids := coalesce((select array_agg(x::uuid) from jsonb_array_elements_text(coalesce(it->'varian_ids', '[]')) x), '{}');
    v_harga := case when v_kanal in ('gofood','grabfood','shopeefood','tiktok') then m.harga_ojol else m.harga_langsung end
      + coalesce((select sum(tambahan_harga) from varian where id = any(v_vids) and menu_id = m.id), 0);
    v_nama := m.nama || coalesce(' (' || (select string_agg(nama, ', ') from varian where id = any(v_vids)) || ')', '');
    v_item_hpp := coalesce((select round(sum(r2.takaran * b2.harga_pokok)) from resep r2 join bahan b2 on b2.id = r2.bahan_id
      where r2.menu_id = m.id and r2.deleted_at is null and (r2.varian_id is null or r2.varian_id = any(v_vids))), 0);
    if m.titipan then v_item_hpp := coalesce(m.harga_titip, 0); end if;
    insert into item_transaksi (transaksi_id, menu_id, varian_ids, nama, qty, harga, hpp_teoritis, catatan)
      values (v_id, m.id, v_vids, v_nama, v_qty, v_harga, v_item_hpp, nullif(it->>'catatan', ''));
    v_sub := v_sub + v_harga * v_qty;
    v_hpp := v_hpp + v_item_hpp * v_qty;
  end loop;

  select batas_diskon_persen into v_batas from perusahaan limit 1;
  if v_diskon > v_sub then raise exception 'Diskon melebihi subtotal'; end if;
  if v_diskon * 100 > v_sub * coalesce(v_batas, 0) and not peran_di_outlet(v_outlet, '{spv}') then
    -- diskon besar: perlu izin SPV sekali pakai (PIN SPV di perangkat kasir)
    select * into v_oto from otorisasi where id = nullif(p->>'otorisasi', '')::uuid and outlet_id = v_outlet and jenis = 'diskon'
      and dipakai_at is null and created_at > now() - interval '10 minutes' for update;
    if v_oto.id is null or v_diskon * 100 > v_sub * v_oto.nilai then
      raise exception 'Diskon di atas % persen perlu persetujuan SPV', v_batas;
    end if;
    update otorisasi set dipakai_at = now() where id = v_oto.id;
    update transaksi set catatan = concat_ws(' · ', catatan, 'Diskon disetujui SPV') where id = v_id;
  end if;
  v_total := v_sub - v_diskon;

  -- pembayaran: satu metode (lama) atau beberapa (split payment)
  v_bayar := case when jsonb_array_length(coalesce(p->'pembayaran', '[]')) > 0 then p->'pembayaran'
                  else jsonb_build_array(jsonb_build_object('metode', p->>'metode', 'nominal', v_total, 'diterima', coalesce((p->>'diterima')::bigint, v_total))) end;
  for b in select * from jsonb_array_elements(v_bayar) loop
    if (b->>'nominal')::bigint <= 0 then raise exception 'Nominal pembayaran tidak valid'; end if;
    v_sum := v_sum + (b->>'nominal')::bigint;
    if b->>'metode' = 'tunai' then
      v_diterima := coalesce((b->>'diterima')::bigint, (b->>'nominal')::bigint);
      if v_diterima < (b->>'nominal')::bigint then raise exception 'Uang diterima kurang'; end if;
      v_kembali := v_kembali + v_diterima - (b->>'nominal')::bigint;
    end if;
  end loop;
  if v_sum <> v_total then raise exception 'Jumlah pembayaran (%) tidak sama dengan total (%)', v_sum, v_total; end if;

  update transaksi set subtotal = v_sub, diskon = v_diskon, total = v_total, hpp_teoritis = v_hpp where id = v_id;
  for b in select * from jsonb_array_elements(v_bayar) loop
    insert into pembayaran (transaksi_id, metode, nominal, diterima)
      values (v_id, (b->>'metode')::metode_bayar, (b->>'nominal')::bigint,
              case when b->>'metode' = 'tunai' then coalesce((b->>'diterima')::bigint, (b->>'nominal')::bigint) end);
  end loop;

  -- kasir → gudang: potong stok bahan di outlet sesuai resep
  for r in
    select ri.bahan_id, sum(ri.takaran * x.qty) jml
      from item_transaksi x join resep ri on ri.menu_id = x.menu_id and ri.deleted_at is null
       and (ri.varian_id is null or ri.varian_id = any(x.varian_ids))
     where x.transaksi_id = v_id group by ri.bahan_id
  loop
    perform geser_stok('asli', v_outlet, r.bahan_id, -r.jml, 'pemakaian', v_id, 'POS #' || v_nomor);
  end loop;

  return jsonb_build_object('id', v_id, 'nomor', v_nomor, 'subtotal', v_sub, 'diskon', v_diskon, 'total', v_total, 'kembalian', v_kembali);
end $function$
;
CREATE OR REPLACE FUNCTION public.geser_stok(p_mode mode_data, p_outlet uuid, p_bahan uuid, p_jumlah numeric, p_jenis text, p_ref uuid, p_ket text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  update stok set jumlah = jumlah + p_jumlah, updated_at = now()
   where mode = p_mode and outlet_id is not distinct from p_outlet and bahan_id = p_bahan;
  if not found then
    insert into stok (mode, outlet_id, bahan_id, jumlah) values (p_mode, p_outlet, p_bahan, p_jumlah);
  end if;
  insert into mutasi_stok (mode, outlet_id, bahan_id, jumlah, jenis, ref_id, keterangan) values (p_mode, p_outlet, p_bahan, p_jumlah, p_jenis, p_ref, p_ket);
end $function$
;
CREATE OR REPLACE FUNCTION public.gudang_pusat()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select punya_peran('{owner,admin_pusat,admin_gudang}')
$function$
;
CREATE OR REPLACE FUNCTION public.info_akun_karyawan()
 RETURNS TABLE(karyawan_id uuid, pengguna_id uuid, email text, ada_pin boolean, peran text[], status text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select k.id, u.id, u.email, u.pin_hash is not null, array(select distinct t.peran::text from penugasan t where t.pengguna_id = u.id), u.status
    from karyawan k left join pengguna u on u.id = k.pengguna_id
   where punya_peran('{owner,hrd}') and k.deleted_at is null and k.mode = 'asli'
$function$
;
CREATE OR REPLACE FUNCTION public.kelola_sdm(o uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select punya_peran('{owner,hrd}') or peran_di_outlet(o, '{spv}')
$function$
;
CREATE OR REPLACE FUNCTION public.operasional_boleh(o uuid, jenis text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
 select auth.uid() is not null and case when jenis='kiriman' then
   punya_peran('{owner,admin_pusat,admin_gudang,finance}') or peran_di_outlet(o,'{kasir,barista,spv}')
 else punya_peran('{owner,admin_pusat,finance}') or peran_di_outlet(o,'{kasir,barista,spv}') end
$function$
;
CREATE OR REPLACE FUNCTION public.peran_di_outlet(p_outlet uuid, p peran[])
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select exists (select 1 from penugasan t join pengguna u on u.id = t.pengguna_id
                 where t.pengguna_id = auth.uid() and u.status = 'aktif' and t.outlet_id = p_outlet and t.peran = any(p));
$function$
;
CREATE OR REPLACE FUNCTION public.punya_peran(p peran[])
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select exists (select 1 from penugasan t join pengguna u on u.id = t.pengguna_id
                 where t.pengguna_id = auth.uid() and u.status = 'aktif' and t.peran = any(p));
$function$
;
CREATE OR REPLACE FUNCTION public.rekap_setoran(p_outlet uuid, p_dari date, p_sampai date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare hasil jsonb;
begin
 if not operasional_boleh(p_outlet,'setoran') then raise exception 'Tidak diizinkan'; end if;
 if p_dari is null or p_sampai is null or p_sampai<p_dari or p_sampai-p_dari>92 then raise exception 'Rentang maksimal 93 hari'; end if;
 with hari as(select generate_series(p_dari,p_sampai,'1 day')::date tanggal),
 pos as(select (t.created_at at time zone 'Asia/Jakarta')::date tanggal,
   sum(p.nominal) filter(where p.metode='tunai') tunai,sum(p.nominal) filter(where p.metode='qris') qris,
   sum(p.nominal) filter(where p.metode not in ('tunai','qris')) non_tunai
   from pembayaran p join transaksi t on t.id=p.transaksi_id where t.outlet_id=p_outlet and t.mode='asli' and t.status='lunas'
   and t.created_at>=(p_dari::timestamp at time zone 'Asia/Jakarta') and t.created_at<((p_sampai+1)::timestamp at time zone 'Asia/Jakarta') group by 1),
 biaya as(select tanggal,sum(jumlah) filter(where sumber='laci') laci,sum(jumlah) filter(where sumber='pusat') pusat from biaya_outlet where outlet_id=p_outlet and mode='asli' and deleted_at is null and tanggal between p_dari and p_sampai group by 1),
 setor as(select a.tanggal,sum(a.jumlah) filter(where s.status='disetujui') disetujui,sum(a.jumlah) filter(where s.status='menunggu') menunggu
   from alokasi_setoran a join setoran_omzet s on s.id=a.setoran_id where s.outlet_id=p_outlet and a.tanggal between p_dari and p_sampai group by 1)
 select coalesce(jsonb_agg(jsonb_build_object('tanggal',h.tanggal,'tunai',coalesce(p.tunai,0),'qris',coalesce(p.qris,0),'non_tunai',coalesce(p.non_tunai,0),
 'pengeluaran_laci',coalesce(b.laci,0),'pengeluaran_pusat',coalesce(b.pusat,0),'modal_ditahan',coalesce(r.modal_ditahan,0),'koreksi',coalesce(r.koreksi,0),'alasan',r.alasan,
 'seharusnya',coalesce(p.tunai,0)-coalesce(b.laci,0)-coalesce(r.modal_ditahan,0)+coalesce(r.koreksi,0),
 'disetujui',coalesce(s.disetujui,0),'menunggu',coalesce(s.menunggu,0),
 'sisa',coalesce(p.tunai,0)-coalesce(b.laci,0)-coalesce(r.modal_ditahan,0)+coalesce(r.koreksi,0)-coalesce(s.disetujui,0)-coalesce(s.menunggu,0)) order by h.tanggal),'[]') into hasil
 from hari h left join pos p using(tanggal) left join biaya b using(tanggal) left join setor s using(tanggal)
 left join rekonsiliasi_kas_harian r on r.outlet_id=p_outlet and r.tanggal=h.tanggal;
 return hasil;
end $function$
;
